def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    mask = (1 << n) - 1
    lamps = int(state[::-1], 2)

    shifts = set()
    for offset in offsets:
        shift = offset % n
        if shift in shifts:
            shifts.remove(shift)
        else:
            shifts.add(shift)

    while t:
        if t & 1:
            new_lamps = 0
            for shift in shifts:
                if shift:
                    new_lamps ^= (lamps >> shift) | (
                        (lamps << (n - shift)) & mask
                    )
                else:
                    new_lamps ^= lamps
            lamps = new_lamps
            if lamps == 0:
                return "0" * n

        t >>= 1
        if t:
            next_shifts = set()
            for shift in shifts:
                doubled = (shift * 2) % n
                if doubled in next_shifts:
                    next_shifts.remove(doubled)
                else:
                    next_shifts.add(doubled)
            shifts = next_shifts

    return format(lamps, f"0{n}b")[::-1]
